import logging
from collections import OrderedDict
from inspect import signature, stack
from logging import getLogger
from os import path
from robot.api import logger

log = getLogger()

_log_input = log.debug
_log_output = log.debug
_log_operation = log.info
_log_warning = log.warning
_log_result = log.info
_log_step = log.debug
_log_iteration = log.debug
_log_env_state = log.debug
_log_deprecation = log.warning
_log_suppression = log.warning
_log_exception = log.error


def log_input_and_output(func):
    """
    Decorator that logs called function name together with passed input parameters and returned output value.

    Usage example:

        @log_input_and_output
        def perform_commissioning(scf_name)
            _start_commissioning(scf_name)
            return _get_commissioning_status()

    Log example:

        Calling perform_commissioning(scf_name='SCF_SISOAUTO001_5G21A.xml')
        Returning from perform_commissioning: Successful
    """
    def wrapper(*args, **kwargs):
        func_name, _args = _get_func_name_and_args(func, args)
        func_args = ', '.join(map(repr, _args))
        func_kwargs = ', '.join(['{}={}'.format(key, repr(value)) for key, value in kwargs.items()])
        func_defaults = ', '.join(['{}={}'.format(
            key, repr(value)) for key, value in _get_defaults(func, args, kwargs).items()])

        _log_input(_msg_template('Calling {name}({args}{comma1}{kwargs}{comma2}{defaults})'.format(
            name=func_name,
            args=func_args,
            comma1=', ' if func_args and func_kwargs else '',
            kwargs=func_kwargs,
            comma2=', ' if (func_args or func_kwargs) and func_defaults else '',
            defaults=func_defaults)))

        output = func(*args, **kwargs)
        _log_output(_msg_template('Returning from {name}: {output}'.format(
            name=func_name,
            output=repr(output))))
        return output

    return wrapper


def log_operation(msg):
    """
    Announces beginning of a major operation which we want to know abut when hunting for Pronto.

    Examples:

        'Waiting for onAir'
        'Performing commissioning'

    :param msg: message to be logged
    :type msg: str
    """
    _log_operation(_msg_template(msg))


def log_result(msg):
    """
    Presents result of a major operation which we want to know about when hunting for Pronto.

    Examples:

        'OnAir reached'
        'Commissioning performed successfully'

    :param msg: message to be logged
    :type msg: str
    """
    _log_result(_msg_template(msg))


def log_step(msg):
    """
    Informs about individual step of more complex algorithm or operation.

    Examples:

        'Finding out ACK Bits value'
        'Checking consistency with equation'
        'Parsing received message'

    :param msg: message to be logged
    :type msg: str
    """
    _log_step(_msg_template(msg))


def log_iteration(msg):
    """
    Informs about step repeated in a loop or recursion.

    Examples:

        'Performing check #{} out of {}'
        'Taking measurement no.{}'
        'Next status to be analysed: {}'

    :param msg: message to be logged
    :type msg: str
    """
    _log_iteration(_msg_template(msg))


def log_env_state(msg):
    """
    Presents current state of test environment (BTS, SCF, Tl config, external database, timestamp, test variables etc).
    Useful when debugging code or confirming Pronto.

    Examples:

        'CPRI links statuses: {}'
        'RU IP address: {}'
        'NIDD parameters: {}'
        'Current date and time: {}'

    :param msg: message to be logged
    :type msg: str
    """
    _log_env_state(_msg_template(msg))


def log_deprecation(msg):
    """
    Informs about deprecated code which should not be used anymore and announces major changes in code behavior.

    Examples:

        '{} param of {} keyword is deprecated and will be removed'
        '{} status not reached - in future this will result in error'

    :param msg: message to be logged
    :type msg: str
    """
    _log_deprecation(_msg_template(msg))


def log_suppression(msg):
    """
    Informs about suppressed exception which doesn't break test execution.

    Examples:

        'During RU status check following exception was ignored: {}'
        'Can't connect with given credentials, retrying with defaults'

    :param msg: message to be logged
    :type msg: str
    """
    _log_suppression(_msg_template(msg))


def log_exception(msg):
    """
    Informs about raised exception which does break test execution.

    Examples:

        'During RU status check following exception occurred: {}'
        'Measurement {} below acceptable threshold of {}'

    :param msg: message to be logged
    :type msg: str
    """
    _log_exception(_msg_template(msg))


def log_warning(msg):
    """
    Presents that there was a warning in the executed operation.

    Examples:

        'During RU status check following exception occurred: {}'
        'Measurement {} below acceptable threshold of {}'

    :param msg: message to be logged
    :type msg: str
    """
    _log_warning(_msg_template(msg))


def log_to_console(msg, newline=True, stream='stdout'):
    """
    Writes the message to the console.

    If the newline argument is True, a newline character is automatically
    added to the message.

    By default, the message is written to the standard output stream.
    Using the standard error stream is possibly by giving
    the stream argument value 'stderr'.
    """
    logger.console(msg=_msg_template(msg=msg), newline=newline, stream=stream)
    _log_operation(_msg_template(msg))


def disable_logging(func, *args, **kwargs):
    """
    Temporarily disables All logging, calls the given function with provided arguments,
    and restores the original log level after execution.

    :param func: Function to call
    :param args: Positional arguments for the function
    :param kwargs: Keyword arguments for the function
    :return: Output from the function
    """
    previous_level = logging.root.manager.disable
    logging.disable(logging.CRITICAL)
    try:
        return func(*args, **kwargs)
    finally:
        logging.disable(previous_level)


def _get_func_name_and_args(func, args):
    args = list(args)
    try:
        sig = signature(func)
        param_names = list(sig.parameters.keys())
        if param_names and param_names[0] == 'self':
            return '{}.{}'.format(args[0].__class__.__name__, func.__name__), args[1:]
    except IndexError:
        pass
    return func.__name__, args


def _get_defaults(function, args, kwargs):
    sig = signature(function)
    param_names = list(sig.parameters.keys())
    defaults = {
        k: v.default for k, v in sig.parameters.items()
        if v.default is not v.empty and k not in kwargs
    }

    if len(args) == len(param_names):
        return {}

    return OrderedDict((key, defaults[key]) for key in param_names[len(args):] if key in defaults)


def _msg_template(msg):
    return '[SISO] {indent_level}{msg}'.format(
        indent_level='' if _get_stack_level() == 0 else "{} ".format("-" * _get_stack_level()),
        msg=msg)


def _get_stack_level():
    path_to_namespace_root_dir = path.dirname(__file__).replace('resources/python/logger', '')
    stack_level = len([el for el in stack() if path_to_namespace_root_dir in el[1]]) - 3
    return 0 if stack_level < 0 else stack_level
